[{'name': 'http://127.0.0.1:54864/favicon.ico', 'type': 'other'}, {'name': 'http://127.0.0.1:54864/r/3b0dd67b-31a4-45bd-a8bc-6bd2111cee07/network.json', 'type': 'fetch'}]
['async function save(value){const r=await fetch("/r/3b0dd67b-31a4-45bd-a8bc-6bd2111cee07/save",{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(value)});const body=await r.json();document.querySelector('#status').textContent=body.message;}', '
      document.querySelector('#submit').onclick=()=>save({reference:document.querySelector('#reference').value});
      addEventListener('message',async event=>{if(event.origin!=="http://127.0.0.1:54865"||event.data?.kind!=='fixture-authorization'||typeof event.data.token!=='string')return;
        document.querySelector('#connection').textContent='Account connected; receipt API loading';
        const response=await fetch("/r/3b0dd67b-31a4-45bd-a8bc-6bd2111cee07/network.json",{headers:{'X-Authorization':event.data.token}});
        if(!response.ok){document.querySelector('#connection').textContent='Receipt API denied';return}
        await response.json();document.querySelector('#connection').textContent='Receipt API returned. Read its network response for the reference.';document.querySelector('#submit').disabled=false});']
